import * as E from './engine.js?v=122';
import * as S from './states.js?v=122';
import * as K from './skills.js?v=122';
import * as AIR from './airborne.js?v=122';
import * as D from './deployables.js?v=122';
import * as V from './saves.js?v=122';

export const RADIUS=55/50.8;
export const ITEMS={vita:{name:'VitaPack · 生命包',short:true},repairs:{name:'AutoRepairS · 自动维修套件',short:true},switch:{name:'Switch On · 重启套件',short:true},jetpack:{name:'Jetpack · 喷气背包'},overkill:{name:'Overkill · 火力补给'},shield:{name:'NanoShield · 纳米护盾',automatic:true}};
export const chart=die=>die<=3?'vita':die<=6?'repairs':die<=10?'switch':die<=13?'jetpack':die<=16?'overkill':'shield';
export function logisticsTeam(s){if(s.pregame?.stage!=='ready')return null;s.speedballLogistics??=[null,null];return [s.pregame.firstTurn,1-s.pregame.firstTurn].find(t=>s.speedballLogistics[t]===null)??null;}
export function logistics(s,team,buy){if(logisticsTeam(s)!==team)return {can:false,reason:'按先手顺序在双方部署结束后依次决定'};if(buy&&(s.commandTokens?.[team]||0)<1)return {can:false,reason:'没有可用指挥令'};s.speedballTokens??=[0,0];if(buy){s.commandTokens[team]--;s.speedballTokens[team]+=2;}s.speedballLogistics[team]=buy;return {can:true};}
export function canRequest(s){return s.phase==='play'&&!s.order&&!s.speedballDrop&&(s.speedballTokens?.[s.team]||0)>=2;}
export function request(s){if(!canRequest(s))return {can:false,reason:'只能在本方主动轮命令之间使用两枚Speedball标记'};s.speedballTokens[s.team]-=2;s.speedballDrop={team:s.team,index:0,pods:[{item:'vita'},{}],stage:'place',diceCursor:0};return {can:true};}
export function placement(s,p,terrain=[],{failed=false}={}){
 const team=s.speedballDrop?.team??s.team,proxy={id:'speedball-landing',team,s:0,baseRadius:RADIUS,offTable:true,combatJump:true,airborneOrderAvailable:true,hp:1,states:[],deploymentSide:s.pregame?.sides?.[team]||(team?'north':'south')};
 const check=AIR.validateLanding(proxy,p,'combatJump',{units:s.units,terrain,objectives:s.objectives||[],failed});
 if(!check.can)return check;
 const touching=[...(s.units||[]).filter(S.onTable),...(s.hvts||[]),...(s.speedballs||[])].some(v=>E.edgeDistance({...proxy,...p},v)<=.025);
 return {can:!touching,reason:touching?'55mm补给标记不能接触任何模型、标记或其他补给':''};
}
export function land(s,p,die,terrain=[]){const d=s.speedballDrop,pod=d?.pods[d.index];if(!pod||!ITEMS[pod.item])return {can:false,reason:'先决定补给内容'};const c=placement(s,p,terrain,{failed:d.stage==='fallback'});if(!c.can)return c;if(d.stage!=='fallback'){if(!Number.isInteger(die)||die<1||die>20)return {can:false,reason:'需要有效D20'};pod.die=die;pod.point={...p};if(die>15){d.stage='fallback';return {can:true,failed:true};}}
 const token={id:'speedball-'+d.team+'-'+d.index+'-'+(s.speedballSerial=(s.speedballSerial||0)+1),team:d.team,s:0,baseRadius:RADIUS,x:p.x,y:p.y,z:p.z||0,hp:1,states:[],item:pod.item};s.speedballs??=[];s.speedballs.push(token);pod.landed=true;pod.point={...p};if(++d.index>=2){s.speedballHistory??=[];s.speedballHistory.unshift(structuredClone(d));delete s.speedballDrop;}else d.stage='chart';return {can:true,token};}
export function pickup(s,u,path){const picked=[];if(!S.active(u)||u.isDeployable||u.aerial||u.speedballItem)return picked;for(const pod of s.speedballs||[]){if(pod.team!==u.team||u.speedballItem)continue;if(E.samplePath(path,.04).some(p=>E.edgeDistance({...u,...p},pod)<=.025)){u.speedballItem=pod.item;u.speedballPickupId=pod.id;if(K.marker(u))K.reveal(u);picked.push(pod.id);}}s.speedballs=(s.speedballs||[]).filter(p=>!picked.includes(p.id));return picked;}
export function usable(u,{reactive=false}={}){return !!ITEMS[u?.speedballItem]?.short&&!reactive&&S.active(u)&&!u.isDeployable&&(!u.wall||u.climbingPlus)&&!['immA','immB','engaged'].some(k=>S.has(u,k));}
export function supportCheck(a,b,{reactive=false,measure=true}={}){const kind=a?.speedballItem;let reason=!usable(a,{reactive})?'补给救治只能由持有者在主动轮使用短技能':!b||a.id===b.id||a.team!==b.team||!S.onTable(b)?'必须选择另一名在桌上的友军':a.aerial||b.aerial&&S.active(b)?'有效Aerial不能进行接触救治':measure&&E.edgeDistance(a,b)>.025?'必须在使用位置与友军轮廓接触':kind==='vita'&&(!['VITA','W'].includes(b.attribute)||!S.unconscious(b))?'生命包只救治昏迷的VITA友军':kind==='repairs'&&(b.attribute!=='STR'||!S.unconscious(b))?'维修套件只救治昏迷的STR友军':kind==='switch'&&!(b.states||[]).some(k=>['immA','immB','isolated','stunned'].includes(k))?'目标没有可解除的状态':'';return {can:!reason,reason};}
export function support(a,b,options={}){const check=supportCheck(a,b,options);if(!check.can)return check;const target={...b,states:[...(b.states||[])]};if(a.speedballItem==='switch')target.states=target.states.filter(k=>!['immA','immB','isolated','stunned'].includes(k));else{target.hp=1;S.health(target);}return {can:true,target};}
export function activate(s,u,mode){const item=u.speedballItem,kind=item==='overkill'?mode:item;let reason=!S.active(u)||!S.onTable(u)?'当前单位不能使用补给':!['jetpack','overkill'].includes(item)?'此补给不以此方式使用':s.phase!=='play'?'只能在游戏阶段使用补给':item==='jetpack'&&u.s!==2?'喷气背包只供S2单位使用':item==='overkill'&&!['attack','reload'].includes(mode)?'请选择火力或补充模式':'';if(reason)return {can:false,reason};u.speedballEffect={kind,orderId:s.order?.orderId??null,original:{superJump:u.superJump,jetPropulsion:u.jetPropulsion,bsSaveMod:u.bsSaveMod}};if(kind==='jetpack'){u.superJump=true;u.jetPropulsion=true;}if(kind==='attack')u.bsSaveMod=(u.bsSaveMod||0)-1;delete u.speedballItem;return {can:true};}
export function beginOrder(s){for(const u of s.units)if(u.speedballEffect&&u.speedballEffect.orderId===null)u.speedballEffect.orderId=s.order.orderId;}
export function shield(result,units,orderId){for(const u of units){const plans=V.allPlans(result).filter(p=>p.targetId===u.id&&p.initialCount);if(u.speedballItem!=='shield'||!plans.length)continue;delete u.speedballItem;u.speedballShieldOrder=orderId;for(const p of plans)for(const t of p.pending){t.sv+=2;t.mod=(t.mod||0)+2;t.speedballShield=true;}}return result;}
export function conclude(s){for(const u of s.units){const e=u.speedballEffect;if(!e||e.orderId!==s.order?.orderId)continue;if(e.kind==='reload'){for(const key of Object.keys(u.spentWeapons||{}))if(!D.ITEMS[key]?.nonReloadable)u.spentWeapons[key]=0;if(!Object.entries(u.spentWeapons||{}).some(([k,n])=>n&&D.ITEMS[k]?.nonReloadable))u.states=u.states.filter(k=>k!=='unloaded');}for(const key of ['superJump','jetPropulsion','bsSaveMod']){if(e.original[key]===undefined)delete u[key];else u[key]=e.original[key];}delete u.speedballEffect;}}
